import math, numpy as np

def nlp_text_classification(train_docs: list, train_labels: list, test_docs: list) -> list:
    classes = sorted(list(set(train_labels)))
    vocab = sorted(list(set(w for d in train_docs for w in d.lower().split())))
    V, w2i = len(vocab), {w: i for i, w in enumerate(vocab)}
    priors = {c: train_labels.count(c)/len(train_docs) for c in classes}
    wc = {c: np.zeros(V) for c in classes}; tw = {c: 0.0 for c in classes}
    for d, l in zip(train_docs, train_labels):
        for w in d.lower().split():
            wc[l][w2i[w]] += 1; tw[l] += 1
    preds = []
    for d in test_docs:
        scores = {c: math.log(priors[c]) + sum(math.log((wc[c][w2i[w]] + 1.0)/(tw[c] + V)) for w in d.lower().split() if w in w2i) for c in classes}
        preds.append(max(scores, key=scores.get))
    return preds
```

